export const DAY=86400000;
export const dateValue=s=>s?Date.parse(s+'T00:00:00Z'):NaN;
export const days=(a,b)=>(dateValue(a)-dateValue(b))/DAY;
export const sum=rows=>rows.reduce((s,e)=>s+(Number(e.workers)||0),0);
export function quantile(values,q){const a=values.filter(Number.isFinite).sort((a,b)=>a-b);if(!a.length)return null;const p=(a.length-1)*q,l=Math.floor(p);return a[l]+(a[Math.ceil(p)]-a[l])*(p-l)}
export function baseline(e,mode='posting'){return mode==='receipt'?e.receivedDate:mode==='interval'?e.firstSeenDate:e.postedDate}
export function news(e,outlet='national'){const a=[e.newsNational,...(outlet==='combined'?[e.newsRegional]:[])].filter(n=>n?.verified&&n.date);return a.sort((a,b)=>a.date.localeCompare(b.date))[0]||null}
export function complete(e,outlet='national'){return e.reviewed===true&&e.searchCompleteNational===true&&(outlet!=='combined'||e.searchCompleteRegional===true)}
export function measure(e,mode='posting',outlet='national'){
 const b=baseline(e,mode),n=[e.newsNational,...(outlet==='combined'?[e.newsRegional]:[])].filter(n=>n?.verified&&n.date&&b&&days(n.date,b)>=-30&&days(n.date,b)<=30).sort((a,b)=>a.date.localeCompare(b.date))[0]||null;const inWindow=!!n;const full=!!b&&complete(e,outlet)&&e.searchStart<=shift(b,-30)&&e.searchEnd>=shift(b,30);
 return {baseline:b,news:inWindow?n:null,delay:inWindow?days(n.date,b):null,range:inWindow&&mode==='interval'&&e.lastAbsentDate?[days(n.date,e.firstSeenDate),days(n.date,e.lastAbsentDate)]:null,eligible:full,status:!full?'incomplete':inWindow?'matched':'none'};
}
export function summarize(rows,mode,outlet){const ms=rows.map(e=>({...measure(e,mode,outlet),event:e}));const eligible=ms.filter(m=>m.eligible),none=eligible.filter(m=>m.status==='none');const matched=ms.filter(m=>m.delay!==null);return {eligible:eligible.length,none:none.length,excluded:rows.length-eligible.length,qci:eligible.length?100*none.length/eligible.length:null,median:quantile(matched.map(m=>m.delay),.5),matched};}
export function shift(s,n){return new Date(dateValue(s)+n*DAY).toISOString().slice(0,10)}
export function group(rows,key){return [...new Set(rows.map(e=>e[key]||'Unknown'))].map(name=>({name,rows:rows.filter(e=>(e[key]||'Unknown')===name)}));}
export function recordDate(e){return e.postedDate||e.listedPostedDate||e.receivedDate||e.processedDate||e.noticeDate||e.effectiveDate||''}
export function makeExamples(){const cities=[['CA','San Francisco',37.77,-122.42],['NY','New York',40.71,-74.01],['WA','Seattle',47.61,-122.33],['CA','Los Angeles',34.05,-118.24],['NY','Buffalo',42.89,-78.88],['WA','Spokane',47.66,-117.43]];const names=['Juniper Systems','Northline Fabrication','Harbor Financial','Cedar Networks','Atlas Components','Meadow Assurance'];return Array.from({length:72},(_,i)=>{const [state,city,lat,lon]=cities[i%6],b=shift('2026-01-06',Math.floor(i/6)*20+i%6),delay=[-12,-6,0,2,4,7,11,16,21,26,8,3][i%12],national=i%4!==0,regional=i%7!==0;return {id:'example-'+i,company:names[i%6]+' (fictional)',state,city,lat,lon,coordinatePrecision:'Illustrative city location',industry:['Information (51)','Manufacturing (31–33)','Finance & insurance (52)'][i%3],workers:35+(i*137%1450),postedDate:i%9===0?null:b,receivedDate:shift(b,-2),firstSeenDate:b,lastAbsentDate:shift(b,-2-i%3),noticeDate:shift(b,-4),effectiveDate:shift(b,60),announcementDate:i%3===0?shift(b,-3):null,newsNational:national?{date:shift(b,delay),verified:true,title:'Fictional national report',url:null}:null,newsRegional:regional?{date:shift(b,delay-3),verified:true,title:'Fictional regional report',url:null}:null,reviewed:i%11!==0,searchCompleteNational:i%11!==0,searchCompleteRegional:i%11!==0,searchStart:shift(b,-35),searchEnd:shift(b,35),sourceTitle:'Illustrative study — not an observed event',sourceUrl:null,sourceDateSemantics:'Fictional dates for demonstrating the research protocol.',synthetic:true,aiAttribution:'Unknown',salaryMedian:null};});}
export function validateImport(value){const rows=Array.isArray(value)?value:value.events;if(!Array.isArray(rows)||!rows.length||rows.length>10000)throw Error('Provide an events array with 1–10,000 records.');const ids=new Set;return rows.map((e,i)=>{if(!e.id||ids.has(e.id)||typeof e.id!=='string')throw Error(`Row ${i+1}: id must be a unique string.`);ids.add(e.id);if(typeof e.company!=='string'||!['CA','NY','WA'].includes(e.state))throw Error(`Row ${i+1}: company and CA/NY/WA state are required.`);if(!Number.isFinite(e.workers)||e.workers<0)throw Error(`Row ${i+1}: workers must be a nonnegative number.`);for(const key of ['postedDate','receivedDate','noticeDate','effectiveDate','firstSeenDate','lastAbsentDate','searchStart','searchEnd'])if(e[key]&&(!/^\d{4}-\d{2}-\d{2}$/.test(e[key])||!Number.isFinite(dateValue(e[key]))||new Date(dateValue(e[key])).toISOString().slice(0,10)!==e[key]))throw Error(`Row ${i+1}: invalid ${key}.`);if(!e.sourceUrl||!/^https:\/\//.test(e.sourceUrl))throw Error(`Row ${i+1}: an HTTPS sourceUrl is required.`);for(const n of [e.newsNational,e.newsRegional])if(n&&(!n.date||!Number.isFinite(dateValue(n.date))||!n.url?.startsWith('https://')))throw Error(`Row ${i+1}: news needs a valid date and HTTPS URL.`);if(e.lat!=null&&(!Number.isFinite(e.lat)||Math.abs(e.lat)>85))throw Error(`Row ${i+1}: invalid latitude.`);if(e.lon!=null&&(!Number.isFinite(e.lon)||Math.abs(e.lon)>180))throw Error(`Row ${i+1}: invalid longitude.`);return {...e,industry:e.industry||'Unknown',synthetic:false};});}
